class StatementService {
    private final ExecutorService io;     // sized for blocking JDBC calls
    private final ExecutorService cpu;    // sized to the cores

    StatementService(ExecutorService io, ExecutorService cpu) { this.io = io; this.cpu = cpu; }

    CompletableFuture<byte[]> statementPdf(String accountId) {
        return CompletableFuture
            .supplyAsync(() -> store.loadRows(accountId), io)   // 1. block on an IO thread
            .thenApplyAsync(renderer::render, cpu);              // 2. render on a CPU thread
        // the caller gets a future; whatever it chains next runs on a cpu thread
    }
}

