class StatementService(
    private val io: CoroutineDispatcher = Dispatchers.IO,
    private val cpu: CoroutineDispatcher = Dispatchers.Default,
) {
    suspend fun statementPdf(accountId: String): ByteArray {
        val rows = withContext(io) { store.loadRows(accountId) }   // 1. block on an IO thread
        return withContext(cpu) { renderer.render(rows) }         // 2. render on a CPU thread
    }   // the caller resumes on its own dispatcher with the bytes
}

