// Java equivalent: a bulkhead pool of exactly 20 threads for the issuer
class AsyncIssuer implements AutoCloseable {
    // 2. a budget sized to the SDK's 20 connections
    private final ExecutorService issuerPool =
        Executors.newFixedThreadPool(20, Thread.ofPlatform().name("issuer-", 0).factory());

    CompletableFuture<CaptureResult> capture(CaptureRequest req) {
        return CompletableFuture.supplyAsync(() -> sdk.capture(req), issuerPool);
    }

    @Override public void close() { issuerPool.shutdown(); }
}

